 		mempool_alloc_bulk(blk_crypto_bounce_page_pool,
 				(void **)pages + nr_allocated,
 				nr_segs - nr_allocated);
-	memalloc_noio_restore(memflags);
+		memalloc_noio_restore(memflags);
+	}
 	*pages_ret = pages;
 	return bio;
 }
